use verus::prelude::*;

verus! {

    /// Given the coefficients c of a polynomial p(x) = c[0] + c[1]·x + … + c[n-1]·xⁿ⁻¹,
    /// return the coefficients of x·p(x).  In other words,
    /// the result has length n+1, result[0] = 0.0, and
    /// for every j < n, result[j+1] = c[j].
    pub fn legmulx(c: Vec<f32>) -> Vec<f32>
        requires
            // input is non‐empty
            c.len() > 0,
        ensures
            // output has length input_length + 1
            result.len() == c.len() + 1,
        ensures
            // first coefficient is 0.0
            result[0] == 0.0,
        ensures
            // shifted coefficients
            forall|j: usize| j < c.len() ==> result[j + 1] == c[j],
    {
        let mut result: Vec<f32> = Vec::new();
        // push the zero coefficient for x^0
        result.push(0.0);

        let mut i: usize = 0;
        // build result[1..] = c[0..]
        while i < c.len() {
            // loop invariants to connect i, result.len(), and the
            // fact that we've already shifted the first i coefficients
            invariant
                i <= c.len();
            invariant
                result.len() == i + 1;
            invariant
                // for all processed indices k < i, result[k+1] == c[k]
                forall|k: usize| k < i ==> result[k + 1] == c[k];
            decreases c.len() - i;
            {
                result.push(c[i]);
                i += 1;
            }
        }

        result
    }

}